/** Only the presenter set ships: a desk with a monitor, microphone, mug and plant, generated by scripts/generate-studio-set.mjs. */
export const STUDIO_SET_PRESETS = ['presenter'] as const;
export type StudioSetPreset = typeof STUDIO_SET_PRESETS[number];
/** A studio set standing in the room: the preset and where its origin is. */
export interface StudioSet { preset: StudioSetPreset; x: number; z: number }
/** The spot id of a set's host position; a script's spot is replaced by it while a set is up. */
export const STUDIO_SET_SPOT = 'studio-set';
